using MediatR;using Namaa.Application.Abstractions.Persistence;using Namaa.Application.AuditLogs.Dtos;using Namaa.Domain.Common.Results;namespace Namaa.Application.AuditLogs.Queries.GetAuditLogById;public sealed class GetAuditLogByIdQueryHandler(IAuditLogRepository repository):IRequestHandler<GetAuditLogByIdQuery,Result<AuditLogDto>>{public async Task<Result<AuditLogDto>>Handle(GetAuditLogByIdQuery request,CancellationToken cancellationToken){var e=await repository.FindByIdAsync(request.Id,cancellationToken);return e is null?Result.Failure<AuditLogDto>(new Error("AuditLogs.NotFound","The audit log was not found.",ErrorType.NotFound)):Result.Success(AuditLogDto.FromEntity(e));}}
